# -*- coding: utf-8 -*-
"""
Package validation is based on global list of validators.

.. note::

    | Each validator **must** accept **single argument** -
    | a path to the downloaded package.
    | and should return bool status (recommended True/False) which will
    | inform if particular step of validation passed or failed.

"""
import os
from zipfile import BadZipfile, ZipFile

from hran_pacman.bases.logger import LOGGER


def file_is_valid_zip(package_path):
    """Zip validator, checks if package is valid ZIP archive.

    :return: **True** if package is valid zip archive,
             **False** if file isn't accessible or it's corrupted.
    """
    try:
        with ZipFile(package_path) as zipf:
            errors = zipf.testzip()
            status = not errors
    except BadZipfile:
        LOGGER.exception("File {} is not a valid zip file".format(package_path))
        status = False
    except IOError:
        LOGGER.exception("Error while opening file {}".format(package_path))
        status = False
    return status


VALIDATORS = [file_is_valid_zip]


def retry_when_file_is_corrupted(func, package_path):
    """Decorator that attempts to call function
    and validation downloaded package.

    If for any reason package didn't pass all the given validations steps,
    decorator will try again up to 3 times.

    :return: operation status, **True** if any attempt will pass with success,
                               **False** in any other case
    """

    def params_wrapper(*func_args, **func_kwargs):
        for attempt in range(1, 4):
            func(*func_args, **func_kwargs)
            validation_statuses = [validator(package_path) for validator in VALIDATORS]
            if all(validation_statuses):
                return True
            else:
                LOGGER.debug("File {} was considered corrupted".format(package_path))
                _print_validation_report(validation_statuses)
                _cleanup_package(package_path)
                LOGGER.debug("Attempt {}/{} failed, retrying".format(attempt, 3))
        LOGGER.debug("Operation {} for {} failed in all {} attempts, aborted".format(func.__name__, package_path, 4))
        return False

    return params_wrapper


def _cleanup_package(package_path):
    if os.path.exists(package_path):
        LOGGER.debug("removing corrupted copy")
        os.remove(package_path)
        LOGGER.debug("corrupted copy removed")


def _print_validation_report(statuses):
    LOGGER.debug("Validations statuses:")
    validators_with_statuses = ["Validator:{} status:{}".format(v, s) for v, s in zip(VALIDATORS, statuses)]
    LOGGER.debug("\n".join(validators_with_statuses))
